import sys
import math

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    A = int(data[0])

    if A == 1:
        print(1)
        return

    max_div = int(math.isqrt(A))
    divisors = []
    for i in range(1, max_div + 1):
        if A % i == 0:
            divisors.append(i)
            if i != A // i:
                divisors.append(A // i)
    divisors.sort()

    # valid_p: list of tuples (p, a, m) where m = (p^a - 1)/(p - 1) divides A
    valid_p = []
    max_p_sieve = max_div + 2
    # Sieve for primes up to max_p_sieve
    sieve = [True] * (max_p_sieve + 1)
    primes_list = []
    if max_p_sieve >= 2:
        sieve[0] = sieve[1] = False
        for i in range(2, max_p_sieve + 1):
            if sieve[i]:
                primes_list.append(i)
                step = i
                start = i * i
                if start > max_p_sieve:
                    continue
                for j in range(start, max_p_sieve + 1, step):
                    sieve[j] = False

    is_prime_set = set(primes_list)

    for m in divisors:
        if m < 3:
            continue
        # Case a = 2
        p = m - 1
        if p >= 2:
            if p <= max_p_sieve:
                is_p = sieve[p]
            else:
                is_p = True
                r = int(math.isqrt(p))
                for pr in primes_list:
                    if pr > r:
                        break
                    if p % pr == 0:
                        is_p = False
                        break
            if is_p:
                valid_p.append((p, 2, m))
        # Cases a >= 3
        max_a = int(math.log(m * 2, 2)) + 2
        for a in range(3, max_a + 1):
            # Binary search for p
            low = 2
            # upper bound for p: p^(a-1) < m => p < m^(1/(a-1))
            high = int(m ** (1.0 / (a - 1))) + 2
            if high < 2:
                continue
            while low <= high:
                mid = (low + high) // 2
                # Compute val = (mid^a - 1) // (mid - 1)
                # Use iterative multiplication to avoid huge numbers early if possible, but Python handles big ints.
                # Check overflow-ish: if mid^a > m * (mid - 1) + 1 roughly.
                # Just compute directly.
                num = pow(mid, a) - 1
                den = mid - 1
                val = num // den
                if val == m:
                    # Check if mid is prime
                    if mid <= max_p_sieve:
                        is_p = sieve[mid]
                    else:
                        is_p = True
                        r = int(math.isqrt(mid))
                        for pr in primes_list:
                            if pr > r:
                                break
                            if mid % pr == 0:
                                is_p = False
                                break
                    if is_p:
                        valid_p.append((mid, a, m))
                    break
                elif val < m:
                    low = mid + 1
                else:
                    high = mid - 1

    # Sort valid_p by p to process in order
    valid_p.sort(key=lambda x: x[0])

    dp = {1: 1}
    i = 0
    n_valid = len(valid_p)
    while i < n_valid:
        p = valid_p[i][0]
        # Group all entries with this p
        group = []
        while i < n_valid and valid_p[i][0] == p:
            group.append(valid_p[i])
            i += 1

        new_dp = dp.copy()
        for prod, count in dp.items():
            for entry in group:
                m_val = entry[2]
                new_prod = prod * m_val
                if A % new_prod == 0:
                    new_dp[new_prod] = new_dp.get(new_prod, 0) + count
        dp = new_dp

    print(dp.get(A, 0))

if __name__ == "__main__":
    solve()
